# -*- coding: utf-8 -*-
# Manual split, G10–G11 (functions, limits, derivatives, approximations, motion). Keys recomputed by hand/sympy.
SPLIT = {}
def P(q, k, d): return {"q": q, "k": k, "d": d}
def T(parent, why, parts): SPLIT[parent] = {"why": why, "parts": parts}
MC = "несколько пунктов в одной задаче с выбором ответа: ответ угадывался сравнением вариантов, на один вопрос уходило время нескольких"

# ---------------------------------------------------------------- G10 composition of functions
FG = r"Даны функции $f(x)=\sqrt{x}$ и $g(x)=\sqrt{2-x}$. "
T("G10_TB_1_4_1_4_2", MC, [
 P(FG + r"Найдите функцию $f(g(x))$ и её область определения.", r"$f(g(x))=\sqrt[4]{2-x}$, $D=(-\infty; 2]$", [
   (r"$f(g(x))=\sqrt{x}\cdot\sqrt{2-x}$, $D=[0; 2]$", r"Ученик перемножил функции вместо подстановки: $f(g(x))$ — это $f$, в которую вместо $x$ подставлено $g(x)$: $\sqrt{\sqrt{2-x}}=\sqrt[4]{2-x}$."),
   (r"$f(g(x))=\sqrt{2-\sqrt{x}}$, $D=[0; 4]$", r"Ученик подставил функции в обратном порядке и нашёл $g(f(x))$; в $f(g(x))$ внутренней является $g$."),
   (r"$f(g(x))=\sqrt[4]{2-x}$, $D=[0; 2]$", r"Ученик добавил условие $x\ge0$ из области определения $f$; но в $f$ подставляется $g(x)=\sqrt{2-x}\ge0$, поэтому ограничение только одно: $2-x\ge0$.")]),
 P(FG + r"Найдите функцию $g(f(x))$ и её область определения.", r"$g(f(x))=\sqrt{2-\sqrt{x}}$, $D=[0; 4]$", [
   (r"$g(f(x))=\sqrt[4]{2-x}$, $D=(-\infty; 2]$", r"Ученик подставил функции в обратном порядке и нашёл $f(g(x))$; в $g(f(x))$ внутренней является $f(x)=\sqrt{x}$."),
   (r"$g(f(x))=\sqrt{2-\sqrt{x}}$, $D=[0; +\infty)$", r"Ученик учёл только $x\ge0$ и забыл условие $2-\sqrt{x}\ge0$, то есть $\sqrt{x}\le2$, $x\le4$."),
   (r"$g(f(x))=\sqrt{2-\sqrt{x}}$, $D=[0; 2]$", r"Ученик решил неравенство $\sqrt{x}\le2$ как $x\le2$, не возведя обе части в квадрат: верно $x\le4$.")]),
 P(FG + r"Найдите функцию $f(f(x))$ и её область определения.", r"$f(f(x))=\sqrt[4]{x}$, $D=[0; +\infty)$", [
   (r"$f(f(x))=x$, $D=[0; +\infty)$", r"Ученик решил, что корень из корня даёт само число, спутав $\sqrt{\sqrt{x}}$ с $\left(\sqrt{x}\right)^{2}$; на самом деле $\sqrt{\sqrt{x}}=\sqrt[4]{x}$."),
   (r"$f(f(x))=\sqrt[4]{x}$, $D=\mathbb{R}$", r"Ученик верно нашёл формулу, но забыл область определения: корень чётной степени определён только при $x\ge0$."),
   (r"$f(f(x))=|x|$, $D=\mathbb{R}$", r"Ученик подставил $x^{2}$ вместо $\sqrt{x}$ и получил $\sqrt{x^{2}}=|x|$; в $f(f(x))$ под корень подставляется $\sqrt{x}$.")]),
 P(FG + r"Найдите функцию $g(g(x))$ и её область определения.", r"$g(g(x))=\sqrt{2-\sqrt{2-x}}$, $D=[-2; 2]$", [
   (r"$g(g(x))=\sqrt{2-\sqrt{2-x}}$, $D=(-\infty; 2]$", r"Ученик учёл только условие $2-x\ge0$ и забыл внешнее: $2-\sqrt{2-x}\ge0$, то есть $2-x\le4$, $x\ge-2$."),
   (r"$g(g(x))=\sqrt{2-\sqrt{2-x}}$, $D=[0; 2]$", r"Ученик решил неравенство $\sqrt{2-x}\le2$ как $2-x\le2$, не возведя $2$ в квадрат: верно $2-x\le4$, $x\ge-2$."),
   (r"$g(g(x))=x$, $D=\mathbb{R}$", r"Ученик решил, что функция, применённая дважды, возвращает $x$, как у взаимно обратных функций; но $g$ не обратна самой себе: $g(g(x))=\sqrt{2-\sqrt{2-x}}$.")]),
])

BOAT = r"Катер движется параллельно берегу с постоянной скоростью $20$ км/ч. В $12{:}00$ он прошёл перед маяком на расстоянии $5$ км от берега. "
T("G10_TB_1_4_1_4_5", MC, [
 P(BOAT + r"Запишите расстояние $s$ (км) между маяком и катером как функцию $s=f(d)$ от расстояния $d$ (км), пройденного катером после $12{:}00$.", r"$s=f(d)=\sqrt{25+d^{2}}$", [
   (r"$s=f(d)=5+d$", r"Ученик сложил катеты вместо применения теоремы Пифагора: $s$ — гипотенуза прямоугольного треугольника с катетами $5$ и $d$."),
   (r"$s=f(d)=\sqrt{d^{2}-25}$", r"Ученик принял $d$ за гипотенузу и вычел квадраты; гипотенуза здесь — искомое расстояние $s$, поэтому $s^{2}=5^{2}+d^{2}$."),
   (r"$s=f(d)=25+d^{2}$", r"Ученик записал $s^{2}=25+d^{2}$, но забыл извлечь корень.")]),
 P(BOAT + r"Запишите расстояние $d$ (км), пройденное катером после $12{:}00$, как функцию $d=g(t)$ от времени $t$ (ч).", r"$d=g(t)=20t$", [
   (r"$d=g(t)=\dfrac{t}{20}$", r"Ученик разделил время на скорость; путь равен скорости, умноженной на время: $d=20t$."),
   (r"$d=g(t)=\dfrac{20}{t}$", r"Ученик разделил скорость на время; путь при равномерном движении равен $vt=20t$."),
   (r"$d=g(t)=20+t$", r"Ученик сложил скорость и время вместо умножения: $d=vt=20t$.")]),
 P(BOAT + r"Пусть $s=f(d)=\sqrt{25+d^{2}}$ — расстояние (км) от маяка до катера, прошедшего $d$ км после $12{:}00$, а $d=g(t)=20t$ — путь за $t$ ч. Найдите сложную функцию $f(g(t))$ и объясните её смысл.",
   r"$f(g(t))=\sqrt{25+400t^{2}}$ — расстояние (км) между катером и маяком через $t$ ч после $12{:}00$", [
   (r"$f(g(t))=20\sqrt{25+t^{2}}$ — расстояние (км) между катером и маяком через $t$ ч после $12{:}00$", r"Ученик умножил всю функцию $f$ на $20$ вместо подстановки $20t$ вместо $d$: $f(20t)=\sqrt{25+(20t)^{2}}$."),
   (r"$f(g(t))=\sqrt{25+20t^{2}}$ — расстояние (км) между катером и маяком через $t$ ч после $12{:}00$", r"Ученик подставил $20t$, но не возвёл $20$ в квадрат: $(20t)^{2}=400t^{2}$."),
   (r"$f(g(t))=\sqrt{25+400t^{2}}$ — путь (км), пройденный катером за $t$ ч", r"Ученик верно составил формулу, но неверно истолковал её: путь катера равен $20t$, а $\sqrt{25+400t^{2}}$ — расстояние от катера до маяка.")]),
])

# ---------------------------------------------------------------- G11 probability
APL = r"В сумке лежат $12$ красных, $10$ зелёных и $3$ жёлтых яблока. Какова вероятность вынуть наугад "
T("G11_TB_22_2_18_2", MC, [
 P(APL + r"яблоко?", r"$1$", [
   (r"$\dfrac{1}{25}$", r"Ученик нашёл вероятность вынуть одно определённое яблоко; в сумке только яблоки, поэтому вынуть яблоко — достоверное событие."),
   (r"$\dfrac{12}{25}$", r"Ученик нашёл вероятность вынуть красное яблоко, а спрашивается про любое яблоко: все $25$ исходов благоприятны."),
   (r"$0$", r"Ученик спутал достоверное событие с невозможным: любой вынутый предмет — яблоко, вероятность равна $1$.")]),
 P(APL + r"грушу?", r"$0$", [
   (r"$1$", r"Ученик спутал невозможное событие с достоверным: груш в сумке нет, благоприятных исходов $0$."),
   (r"$\dfrac{1}{25}$", r"Ученик посчитал одну грушу среди $25$ предметов, но груш в сумке нет: благоприятных исходов $0$."),
   (r"$\dfrac{1}{26}$", r"Ученик добавил грушу к содержимому сумки; в сумке только $25$ яблок, вынуть грушу невозможно.")]),
 P(APL + r"зелёное яблоко?", r"$\dfrac{2}{5}$", [
   (r"$\dfrac{1}{10}$", r"Ученик нашёл вероятность вынуть одно определённое зелёное яблоко из $10$ зелёных; благоприятных исходов $10$ из $25$."),
   (r"$\dfrac{2}{3}$", r"Ученик разделил $10$ зелёных на $15$ не красных яблок; всего в сумке $25$ яблок: $\dfrac{10}{25}=\dfrac{2}{5}$."),
   (r"$\dfrac{3}{5}$", r"Ученик нашёл вероятность вынуть не зелёное яблоко: $\dfrac{15}{25}$; зелёных $10$ из $25$.")]),
 P(APL + r"не красное яблоко?", r"$\dfrac{13}{25}$", [
   (r"$\dfrac{12}{25}$", r"Ученик нашёл вероятность вынуть красное яблоко; не красных $10+3=13$."),
   (r"$\dfrac{2}{5}$", r"Ученик учёл только зелёные яблоки и забыл жёлтые: не красных $10+3=13$ из $25$."),
   (r"$\dfrac{3}{25}$", r"Ученик учёл только жёлтые яблоки и забыл зелёные: не красных $10+3=13$ из $25$.")]),
])

# ---------------------------------------------------------------- G11 limits: meaning of notation
T("G11_TB_2_2_2_2", MC, [
 P(r"Объясните, что означает запись $\displaystyle\lim_{x\to+\infty}\left(2+\dfrac{1}{x}\right)=2$.", r"При неограниченном возрастании $x$ значения $2+\dfrac{1}{x}$ сколь угодно близко приближаются к $2$", [
   (r"При $x=+\infty$ значение функции $2+\dfrac{1}{x}$ равно $2$", r"Ученик понимает предел как значение функции в «точке» $+\infty$; но $+\infty$ — не число, а сама функция нигде не равна $2$, так как $\dfrac{1}{x}\ne0$."),
   (r"При неограниченном возрастании $x$ значения $2+\dfrac{1}{x}$ неограниченно возрастают", r"Ученик решил, что с ростом $x$ растёт и функция; но $\dfrac{1}{x}\to0$, поэтому значения приближаются к $2$."),
   (r"При $x$, близких к $0$, значения $2+\dfrac{1}{x}$ близки к $2$", r"Ученик спутал $x\to+\infty$ с $x\to0$; при $x$, близких к $0$, дробь $\dfrac{1}{x}$ неограниченна.")]),
 P(r"Объясните, что означает запись $\displaystyle\lim_{x\to-3}x^{2}=9$.", r"При $x$, сколь угодно близких к $-3$, значения $x^{2}$ сколь угодно близки к $9$", [
   (r"При $x$, близких к $-3$, значения $x^{2}$ близки к $-9$", r"Ученик ошибся в знаке: $(-3)^{2}=9$, квадрат числа неотрицателен."),
   (r"При $x$, близких к $9$, значения $x^{2}$ близки к $-3$", r"Ученик поменял местами аргумент и значение: под знаком предела указано, к чему стремится $x$ ($-3$), а справа — к чему стремится функция ($9$)."),
   (r"При неограниченном убывании $x$ значения $x^{2}$ приближаются к $9$", r"Ученик спутал $x\to-3$ с $x\to-\infty$; при $x\to-\infty$ значения $x^{2}$ неограниченно растут.")]),
 P(r"Объясните, что означает запись $\displaystyle\lim_{x\to5}\dfrac{1}{|x-5|}=+\infty$.", r"При $x$, стремящемся к $5$, значения $\dfrac{1}{|x-5|}$ положительны и неограниченно возрастают", [
   (r"При $x=5$ значение $\dfrac{1}{|x-5|}$ равно $+\infty$", r"Ученик понимает предел как значение в точке; при $x=5$ функция не определена, запись описывает её поведение вблизи $5$."),
   (r"При $x$, стремящемся к $5$, значения $\dfrac{1}{|x-5|}$ стремятся к $0$", r"Ученик решил, что если знаменатель стремится к $0$, то и дробь стремится к $0$; наоборот, дробь с малым положительным знаменателем неограниченно растёт."),
   (r"При $x$, стремящемся к $5$, модуль $\dfrac{1}{|x-5|}$ растёт, а знак меняется", r"Ученик перенёс свойство функции $\dfrac{1}{x-5}$; но $|x-5|>0$, дробь всегда положительна — поэтому предел $+\infty$.")]),
 P(r"Объясните, что означает запись $\displaystyle\lim_{x\to5}\dfrac{1}{x-5}=\infty$ (запись $\lim f(x)=\infty$ означает, что $\lim|f(x)|=+\infty$).", r"При $x$, стремящемся к $5$, модуль значений $\dfrac{1}{x-5}$ неограниченно возрастает (слева от $5$ значения отрицательны, справа — положительны)", [
   (r"При $x$, стремящемся к $5$, значения $\dfrac{1}{x-5}$ неограниченно возрастают, оставаясь положительными", r"Ученик спутал $\infty$ с $+\infty$: при $x<5$ дробь отрицательна, неограниченно растёт только её модуль."),
   (r"При $x$, стремящемся к $5$, значения $\dfrac{1}{x-5}$ стремятся к $0$", r"Ученик решил, что если знаменатель стремится к $0$, то и дробь стремится к $0$; наоборот, модуль дроби неограниченно растёт."),
   (r"Функция $\dfrac{1}{x-5}$ предела при $x\to5$ не имеет, поэтому запись неверна", r"Ученик не учёл соглашение: запись $\lim f(x)=\infty$ означает $\lim|f(x)|=+\infty$, а $\left|\dfrac{1}{x-5}\right|\to+\infty$ при $x\to5$.")]),
])

T("G11_TB_2_2_2_3", MC, [
 P(r"Объясните, почему верно равенство $\displaystyle\lim_{x\to1}\dfrac{1}{|x-1|}=+\infty$.", r"Знаменатель $|x-1|$ положителен и стремится к $0$, поэтому дробь $\dfrac{1}{|x-1|}$ положительна и неограниченно возрастает", [
   (r"При $x=1$ получаем $1:0=+\infty$", r"Ученик разделил на нуль; деление на нуль не определено, а равенство описывает поведение дроби при $x$, близких к $1$."),
   (r"Знаменатель $|x-1|$ стремится к $+\infty$, поэтому дробь положительна и растёт", r"Ученик ошибся в поведении знаменателя: при $x\to1$ величина $|x-1|$ стремится к $0$, а не к $+\infty$ (при таком знаменателе дробь стремилась бы к $0$)."),
   (r"Знаменатель $|x-1|$ меняет знак при переходе через $1$, поэтому модуль дроби неограниченно возрастает", r"Ученик не учёл модуль: $|x-1|\ge0$ и знак не меняет; именно поэтому дробь положительна и предел равен $+\infty$, а не $\infty$.")]),
 P(r"Объясните, почему верно равенство $\displaystyle\lim_{x\to-1}\dfrac{-1}{(x+1)^{2}}=-\infty$.", r"Знаменатель $(x+1)^{2}$ положителен и стремится к $0$, числитель равен $-1$, поэтому дробь отрицательна и её модуль неограниченно возрастает", [
   (r"Знаменатель $(x+1)^{2}$ стремится к $0$, меняя знак, поэтому дробь стремится к $-\infty$", r"Ученик ошибся: квадрат не меняет знак; если бы знаменатель менял знак, дробь не могла бы стремиться именно к $-\infty$."),
   (r"Знаменатель $(x+1)^{2}$ стремится к $0$, поэтому дробь стремится к $0$", r"Ученик решил, что при знаменателе, стремящемся к $0$, дробь стремится к $0$; наоборот, её модуль неограниченно растёт."),
   (r"Числитель отрицателен, а знаменатель $(x+1)^{2}$ стремится к $+\infty$, поэтому дробь стремится к $-\infty$", r"Ученик ошибся в поведении знаменателя: при $x\to-1$ он стремится к $0$; при знаменателе, стремящемся к $+\infty$, дробь стремилась бы к $0$.")]),
 P(r"Объясните, почему верно равенство $\displaystyle\lim_{x\to2}\dfrac{1}{(x-2)^{3}}=\infty$ (запись $\lim f(x)=\infty$ означает, что $\lim|f(x)|=+\infty$).", r"Знаменатель $(x-2)^{3}$ стремится к $0$ и меняет знак при переходе через $2$, поэтому модуль дроби неограниченно возрастает, а знак зависит от стороны", [
   (r"Знаменатель $(x-2)^{3}$ положителен и стремится к $0$, поэтому дробь стремится к $+\infty$", r"Ученик не учёл, что куб отрицательного числа отрицателен: при $x<2$ дробь отрицательна, поэтому пишут $\infty$ без знака."),
   (r"Знаменатель $(x-2)^{3}$ стремится к $0$, поэтому дробь стремится к $0$", r"Ученик решил, что при знаменателе, стремящемся к $0$, дробь стремится к $0$; наоборот, её модуль неограниченно растёт."),
   (r"Куб в знаменателе растёт быстрее числителя, поэтому дробь неограниченно возрастает", r"Ученик спутал $x\to2$ с $x\to\infty$: при $x\to2$ знаменатель мал, а при большом знаменателе дробь была бы малой.")]),
 P(r"Объясните, почему верно равенство $\displaystyle\lim_{x\to-2}\dfrac{-3}{x+2}=\infty$ (запись $\lim f(x)=\infty$ означает, что $\lim|f(x)|=+\infty$).", r"Знаменатель $x+2$ стремится к $0$ и меняет знак при переходе через $-2$, поэтому модуль дроби $\dfrac{-3}{x+2}$ неограниченно возрастает", [
   (r"Числитель отрицателен, поэтому дробь стремится к $-\infty$", r"Ученик не учёл знак знаменателя: при $x<-2$ он отрицателен и дробь положительна, неограниченно растёт только модуль."),
   (r"Знаменатель $x+2$ стремится к $0$, поэтому дробь стремится к $0$", r"Ученик решил, что при знаменателе, стремящемся к $0$, дробь стремится к $0$; наоборот, её модуль неограниченно растёт."),
   (r"Знаменатель $x+2$ положителен и стремится к $0$, поэтому дробь стремится к $-\infty$", r"Ученик рассмотрел только $x>-2$; при $x<-2$ знаменатель отрицателен и дробь положительна, поэтому предел равен $\infty$ без знака.")]),
])

LIM = r" ($[x]$ — целая часть числа $x$; запись $\lim f(x)=\infty$ означает, что $\lim|f(x)|=+\infty$)."
def lim_part(expr, absf, sign_note):
    return P(r"Определите, чему равен предел $\displaystyle" + expr + "$" + LIM, r"$\infty$", [
        (r"$+\infty$", r"Ученик не учёл множитель, меняющий знак: " + sign_note + r" Неограниченно растёт только модуль $" + absf + r"$, поэтому предел равен $\infty$."),
        (r"$-\infty$", r"Ученик решил, что значения отрицательны; но " + sign_note + r" Предел равен $\infty$, так как $" + absf + r"\to+\infty$."),
        (r"предел не существует", r"Ученик не учёл определение из учебника: $\lim f(x)=\infty$, если $|f(x)|\to+\infty$; здесь $" + absf + r"\to+\infty$, поэтому предел равен $\infty$.")])
T("G11_TB_2_2_2_5", MC + r"; ключ «не существует» для всех шести пунктов противоречил определению учебника (Никольский, 11 кл., § 2.1): пишут $\lim f=\infty$, если $\lim|f|=+\infty$; во всех пунктах модуль неограниченно растёт, а знак колеблется, поэтому предел равен $\infty$", [
 lim_part(r"\lim_{x\to+\infty}(-1)^{[x]}\cdot x^{3}", r"|x|^{3}", r"множитель $(-1)^{[x]}$ равен то $1$, то $-1$ на соседних единичных отрезках."),
 lim_part(r"\lim_{x\to-\infty}(-1)^{[x]}\cdot x^{3}", r"|x|^{3}", r"множитель $(-1)^{[x]}$ равен то $1$, то $-1$ на соседних единичных отрезках."),
 lim_part(r"\lim_{x\to0}\dfrac{(-1)^{\left[\frac{1}{x}\right]}}{x}", r"\dfrac{1}{|x|}", r"при $x\to0$ целая часть $\left[\dfrac{1}{x}\right]$ пробегает все целые значения, и множитель $(-1)^{\left[\frac{1}{x}\right]}$ меняет знак."),
 lim_part(r"\lim_{x\to0}\dfrac{(-1)^{\left[\frac{1}{x}\right]}}{x^{2}}", r"\dfrac{1}{x^{2}}", r"хотя $x^{2}>0$, множитель $(-1)^{\left[\frac{1}{x}\right]}$ при $x\to0$ меняет знак бесконечно много раз."),
 lim_part(r"\lim_{x\to+\infty}(-2)^{[x]}", r"2^{[x]}", r"степень $(-2)^{[x]}$ положительна при чётном $[x]$ и отрицательна при нечётном."),
 lim_part(r"\lim_{x\to+\infty}(-\pi)^{[x]}", r"\pi^{[x]}", r"степень $(-\pi)^{[x]}$ положительна при чётном $[x]$ и отрицательна при нечётном."),
])

# ---------------------------------------------------------------- G11 increments and velocity, s = t^2
ST = r"Точка движется прямолинейно по закону $s=t^{2}$. "
T("G11_TB_4_1_4_1", MC, [
 P(ST + r"Найдите приращение времени $\Delta t$ на промежутке от $t_{1}=1$ до $t_{2}=2$.", r"$1$", [
   (r"$3$", r"Ученик нашёл приращение пути $\Delta s=s(2)-s(1)=3$ вместо приращения времени $\Delta t=t_{2}-t_{1}=1$."),
   (r"$2$", r"Ученик взял конечный момент $t_{2}=2$ вместо разности $t_{2}-t_{1}=1$."),
   (r"$-1$", r"Ученик вычел в обратном порядке: $\Delta t=t_{2}-t_{1}=2-1=1$, а не $t_{1}-t_{2}$.")]),
 P(ST + r"Найдите приращение пути $\Delta s$ на промежутке времени от $t_{1}=1$ до $t_{2}=2$.", r"$3$", [
   (r"$1$", r"Ученик нашёл приращение времени $\Delta t=1$; приращение пути $\Delta s=s(2)-s(1)=4-1=3$."),
   (r"$4$", r"Ученик нашёл путь в момент $t_{2}$: $s(2)=4$, но не вычел $s(1)=1$."),
   (r"$2$", r"Ученик подставил моменты времени в $2t$ вместо закона $s=t^{2}$: $2\cdot2-2\cdot1=2$.")]),
 P(ST + r"Найдите среднюю скорость на промежутке времени от $t_{1}=1$ до $t_{2}=2$.", r"$3$", [
   (r"$4$", r"Ученик нашёл мгновенную скорость в момент $t=2$: $s'(2)=4$; средняя скорость равна $\dfrac{\Delta s}{\Delta t}=\dfrac{3}{1}=3$."),
   (r"$2$", r"Ученик нашёл мгновенную скорость в момент $t=1$: $s'(1)=2$; средняя скорость равна $\dfrac{\Delta s}{\Delta t}=3$."),
   (r"$\dfrac{1}{3}$", r"Ученик разделил приращение времени на приращение пути; средняя скорость $\dfrac{\Delta s}{\Delta t}=3$.")]),
])
T("G11_TB_4_1_4_2", MC + r"; условие ссылалось на задание 4.1 — теперь закон движения указан в каждом пункте", [
 P(ST + r"Найдите приращение пути $\Delta s$ на промежутке времени от $t$ до $t+\Delta t$.", r"$2t\Delta t+(\Delta t)^{2}$", [
   (r"$(\Delta t)^{2}$", r"Ученик возвёл сумму в квадрат без удвоенного произведения: $(t+\Delta t)^{2}=t^{2}+2t\Delta t+(\Delta t)^{2}$."),
   (r"$2t\Delta t$", r"Ученик отбросил слагаемое $(\Delta t)^{2}$; оно входит в точное приращение $\Delta s=(t+\Delta t)^{2}-t^{2}$."),
   (r"$t^{2}+2t\Delta t+(\Delta t)^{2}$", r"Ученик нашёл путь $s(t+\Delta t)$, но не вычел $s(t)=t^{2}$.")]),
 P(ST + r"Найдите среднюю скорость на промежутке времени от $t$ до $t+\Delta t$.", r"$2t+\Delta t$", [
   (r"$2t$", r"Ученик нашёл мгновенную скорость в момент $t$; средняя скорость $\dfrac{\Delta s}{\Delta t}=\dfrac{2t\Delta t+(\Delta t)^{2}}{\Delta t}=2t+\Delta t$."),
   (r"$2t\Delta t+(\Delta t)^{2}$", r"Ученик нашёл приращение пути, но не разделил его на $\Delta t$."),
   (r"$2t+(\Delta t)^{2}$", r"Ученик разделил на $\Delta t$ только первое слагаемое; $\dfrac{(\Delta t)^{2}}{\Delta t}=\Delta t$.")]),
 P(ST + r"Найдите мгновенную скорость в момент времени $t$.", r"$2t$", [
   (r"$2t+\Delta t$", r"Ученик нашёл среднюю скорость, но не перешёл к пределу при $\Delta t\to0$: $v(t)=\lim\limits_{\Delta t\to0}(2t+\Delta t)=2t$."),
   (r"$t^{2}$", r"Ученик записал закон движения вместо скорости; скорость — производная пути: $s'(t)=2t$."),
   (r"$t$", r"Ученик разделил путь на время: $\dfrac{t^{2}}{t}=t$ — это средняя скорость на $[0; t]$, а не мгновенная.")]),
 P(ST + r"Найдите мгновенную скорость в момент времени $t=1$.", r"$2$", [
   (r"$1$", r"Ученик нашёл путь $s(1)=1$ вместо скорости $s'(1)=2\cdot1=2$."),
   (r"$3$", r"Ученик нашёл среднюю скорость на промежутке $[1; 2]$; мгновенная скорость в момент $t=1$ равна $s'(1)=2$."),
   (r"$2+\Delta t$", r"Ученик подставил $t=1$ в среднюю скорость $2t+\Delta t$ и не перешёл к пределу при $\Delta t\to0$.")]),
])

# ---------------------------------------------------------------- G11 derivative of sqrt(quadratic) — two meaningful questions per function
def sq(parent, f, bad, badw, zero_key, zero_d, sign_key, sign_d):
    T(parent, MC + r"; пункты «непрерывна ли функция» и «в каждой ли точке есть производная» вошли в формулировку вопросов", [
      P(r"Функция $y=" + f + r"$ непрерывна в каждой точке своей области определения. В каких точках она не имеет производной?", zero_key, zero_d),
      P(r"При каких значениях $x$ производная функции $y=" + f + r"$ положительна, отрицательна, равна нулю?", sign_key, sign_d)])
sq("G11_TB_4_4_4_25_1", r"\sqrt{x^{2}+6x+9}", None, None, r"$x=-3$", [
   (r"$x=3$", r"Ученик ошибся в знаке: $\sqrt{x^{2}+6x+9}=|x+3|$, излом графика — в точке $x=-3$."),
   (r"$x=-3$ и $x=3$", r"Ученик решил уравнение $x^{2}=9$ вместо $(x+3)^{2}=0$; функция $y=|x+3|$ имеет единственный излом при $x=-3$."),
   (r"производная существует во всех точках", r"Ученик решил, что непрерывная функция дифференцируема; но $y=|x+3|$ имеет излом при $x=-3$: производная слева $-1$, справа $1$.")],
  r"$y'>0$ при $x>-3$; $y'<0$ при $x<-3$; $y'=0$ ни при каких $x$", [
   (r"$y'>0$ при $x>-3$; $y'<0$ при $x<-3$; $y'=0$ при $x=-3$", r"Ученик решил, что в точке минимума производная равна нулю, как у параболы; но при $x=-3$ у функции $|x+3|$ производной нет."),
   (r"$y'>0$ при $x<-3$; $y'<0$ при $x>-3$; $y'=0$ ни при каких $x$", r"Ученик перепутал знаки: $y=|x+3|$ при $x>-3$ равна $x+3$ и возрастает, $y'=1>0$."),
   (r"$y'>0$ при всех $x\ne-3$", r"Ученик не учёл, что при $x<-3$ функция равна $-(x+3)$ и убывает: там $y'=-1<0$.")])
sq("G11_TB_4_4_4_25_2", r"\sqrt{4x^{2}-4x+1}", None, None, r"$x=\dfrac{1}{2}$", [
   (r"$x=-\dfrac{1}{2}$", r"Ученик ошибся в знаке: $\sqrt{4x^{2}-4x+1}=|2x-1|$, излом графика — в точке $x=\dfrac{1}{2}$."),
   (r"$x=1$", r"Ученик нашёл нуль выражения $2x-1$ как $x=1$, не разделив на $2$: $2x-1=0$ при $x=\dfrac{1}{2}$."),
   (r"производная существует во всех точках", r"Ученик решил, что непрерывная функция дифференцируема; но $y=|2x-1|$ имеет излом при $x=\dfrac{1}{2}$: производная слева $-2$, справа $2$.")],
  r"$y'>0$ при $x>\dfrac{1}{2}$; $y'<0$ при $x<\dfrac{1}{2}$; $y'=0$ ни при каких $x$", [
   (r"$y'>0$ при $x>\dfrac{1}{2}$; $y'<0$ при $x<\dfrac{1}{2}$; $y'=0$ при $x=\dfrac{1}{2}$", r"Ученик решил, что в точке минимума производная равна нулю; но при $x=\dfrac{1}{2}$ у функции $|2x-1|$ производной нет."),
   (r"$y'>0$ при $x<\dfrac{1}{2}$; $y'<0$ при $x>\dfrac{1}{2}$; $y'=0$ ни при каких $x$", r"Ученик перепутал знаки: при $x>\dfrac{1}{2}$ функция равна $2x-1$ и возрастает, $y'=2>0$."),
   (r"$y'>0$ при всех $x\ne\dfrac{1}{2}$", r"Ученик не учёл, что при $x<\dfrac{1}{2}$ функция равна $1-2x$ и убывает: там $y'=-2<0$.")])
sq("G11_TB_4_4_4_25_3", r"\sqrt{-x^{2}+x+6}", None, None, r"$x=-2$ и $x=3$", [
   (r"$x=\dfrac{1}{2}$", r"Ученик указал вершину параболы под корнем; там производная существует и равна нулю, а не существует она на концах области определения $[-2; 3]$, где подкоренное выражение обращается в нуль."),
   (r"$x=2$ и $x=-3$", r"Ученик ошибся в знаках корней уравнения $-x^{2}+x+6=0$; его корни $-2$ и $3$."),
   (r"производная существует во всех точках области определения", r"Ученик не учёл концы отрезка $[-2; 3]$: производная $\dfrac{-2x+1}{2\sqrt{-x^{2}+x+6}}$ при $x=-2$ и $x=3$ не определена.")],
  r"$y'=0$ при $x=\dfrac{1}{2}$; $y'>0$ при $-2<x<\dfrac{1}{2}$; $y'<0$ при $\dfrac{1}{2}<x<3$", [
   (r"$y'=0$ при $x=\dfrac{1}{2}$; $y'>0$ при $\dfrac{1}{2}<x<3$; $y'<0$ при $-2<x<\dfrac{1}{2}$", r"Ученик перепутал знаки: $y'=\dfrac{1-2x}{2\sqrt{-x^{2}+x+6}}$ положительна при $x<\dfrac{1}{2}$."),
   (r"$y'=0$ при $x=\dfrac{1}{2}$; $y'>0$ при $x<\dfrac{1}{2}$; $y'<0$ при $x>\dfrac{1}{2}$", r"Ученик не учёл область определения: функция определена только на $[-2; 3]$."),
   (r"$y'=0$ при $x=-2$ и $x=3$; $y'>0$ при $-2<x<\dfrac{1}{2}$; $y'<0$ при $\dfrac{1}{2}<x<3$", r"Ученик принял нули подкоренного выражения за нули производной; в точках $-2$ и $3$ производной нет, а равна нулю она при $x=\dfrac{1}{2}$.")])
sq("G11_TB_4_4_4_25_4", r"\sqrt{-x^{2}+2x+8}", None, None, r"$x=-2$ и $x=4$", [
   (r"$x=1$", r"Ученик указал вершину параболы под корнем; там производная равна нулю, а не существует она на концах области определения $[-2; 4]$."),
   (r"$x=2$ и $x=-4$", r"Ученик ошибся в знаках корней уравнения $-x^{2}+2x+8=0$; его корни $-2$ и $4$."),
   (r"производная существует во всех точках области определения", r"Ученик не учёл концы отрезка $[-2; 4]$: производная $\dfrac{-2x+2}{2\sqrt{-x^{2}+2x+8}}$ при $x=-2$ и $x=4$ не определена.")],
  r"$y'=0$ при $x=1$; $y'>0$ при $-2<x<1$; $y'<0$ при $1<x<4$", [
   (r"$y'=0$ при $x=1$; $y'>0$ при $1<x<4$; $y'<0$ при $-2<x<1$", r"Ученик перепутал знаки: $y'=\dfrac{1-x}{\sqrt{-x^{2}+2x+8}}$ положительна при $x<1$."),
   (r"$y'=0$ при $x=1$; $y'>0$ при $x<1$; $y'<0$ при $x>1$", r"Ученик не учёл область определения: функция определена только на $[-2; 4]$."),
   (r"$y'=0$ при $x=-2$ и $x=4$; $y'>0$ при $-2<x<1$; $y'<0$ при $1<x<4$", r"Ученик принял нули подкоренного выражения за нули производной; в точках $-2$ и $4$ производной нет, а равна нулю она при $x=1$.")])

# ---------------------------------------------------------------- G11 statue (optimal viewing distance x = sqrt((b-c)(a+b-c)))
STAT = r"Статуя высотой $a$ м стоит на постаменте высотой $b$ м. Наблюдатель, рост которого до уровня глаз $c$ м ($c<b$), хочет видеть статую под наибольшим углом. На каком расстоянии от основания постамента он должен встать, если "
T("G11_TB_5_10*_5_101", MC + r"; ссылка на рисунок убрана — условие полное без него", [
 P(STAT + r"$a=3$, $b=2{,}5$, $c=1{,}5$? Шириной постамента пренебречь.", r"$2$ м", [
   (r"$2{,}5$ м", r"Ученик взял среднее арифметическое высот $\dfrac{1+4}{2}$ над уровнем глаз; наибольший угол даёт среднее геометрическое $\sqrt{(b-c)(a+b-c)}=\sqrt{1\cdot4}=2$."),
   (r"$4$ м", r"Ученик взял высоту верхушки статуи над уровнем глаз $a+b-c=4$; оптимальное расстояние $\sqrt{(b-c)(a+b-c)}=2$."),
   (r"$\sqrt{13{,}75}$ м", r"Ученик не учёл рост наблюдателя и взял высоты от земли: $\sqrt{b(a+b)}$; углы отсчитываются от уровня глаз, поэтому нужны $b-c$ и $a+b-c$.")]),
 P(STAT + r"$a=6$, $b=3{,}7$, $c=1{,}7$? Шириной постамента пренебречь.", r"$4$ м", [
   (r"$5$ м", r"Ученик взял среднее арифметическое высот $\dfrac{2+8}{2}$ над уровнем глаз; наибольший угол даёт среднее геометрическое $\sqrt{(b-c)(a+b-c)}=\sqrt{2\cdot8}=4$."),
   (r"$8$ м", r"Ученик взял высоту верхушки статуи над уровнем глаз $a+b-c=8$; оптимальное расстояние $\sqrt{(b-c)(a+b-c)}=4$."),
   (r"$\sqrt{35{,}89}$ м", r"Ученик не учёл рост наблюдателя и взял высоты от земли: $\sqrt{b(a+b)}$; углы отсчитываются от уровня глаз.")]),
])

